result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ini2json.py", "content": "#!/usr/bin/env python3
"""Convert an INI file into nested JSON: {section: {key: value}}.

Usage:
    python ini2json.py input.ini [-o output.json] [--typed] [--apply-defaults]

Options:
    --typed           Coerce values to int, float, or bool (true/false).
                      Values that fail coercion remain strings.
    --apply-defaults  Merge keys from the [DEFAULT] section into every
                      section. Without this flag the DEFAULT section is
                      emitted as its own section and other sections
                      contain only their own keys.
"""

import argparse
import configparser
import json
import sys

_SECTION_RE = configparser.ConfigParser.SECTCRE


def coerce(value):
    """Try to convert *value* to int, float, then bool; else stay str."""
    v = value.strip()
    try:
        return int(v)
    except ValueError:
        pass
    try:
        return float(v)
    except ValueError:
        pass
    low = v.lower()
    if low == "true":
        return True
    if low == "false":
        return False
    return value


def _text_without_default_section(text):
    """Return *text* with the entire [DEFAULT] section removed."""
    out = []
    skipping = False
    for line in text.splitlines():
        match = _SECTION_RE.match(line.strip())
        if match:
            skipping = match.group(1).lower() == "default"
            if skipping:
                continue
        elif not skipping:
            out.append(line)
    return "\n".join(out)


def ini_to_dict(path, typed=False, apply_defaults=False):
    """Parse the INI file at *path* into a nested dict."""
    with open(path, "r", encoding="utf-8") as fh:
        text = fh.read()

    parser = configparser.ConfigParser()
    parser.read_string(text)
    defaults = dict(parser.defaults())

    result = {}
    if apply_defaults:
        # parser.items(section) already includes DEFAULT keys.
        for section in parser.sections():
            result[section] = dict(parser.items(section))
    else:
        bare = configparser.ConfigParser()
        bare.read_string(_text_without_default_section(text))
        for section in bare.sections():
            result[section] = dict(bare.items(section))
        if defaults:
            result["DEFAULT"] = defaults

    if typed:
        result = {
            section: {key: coerce(value) for key, value in pairs.items()}
            for section, pairs in result.items()
        }
    return result


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("ini", help="input INI file")
    ap.add_argument("-o", "--output", help="output JSON file (default stdout)")
    ap.add_argument("--typed", action="store_true",
                    help="coerce ints, floats and true/false booleans")
    ap.add_argument("--apply-defaults", action="store_true",
                    help="merge [DEFAULT] keys into every section")
    args = ap.parse_args(argv)

    data = ini_to_dict(args.ini, typed=args.typed,
                       apply_defaults=args.apply_defaults)
    output = json.dumps(data, indent=2, sort_keys=True)
    if args.output:
        with open(args.output, "w", encoding="utf-8") as fh:
            fh.write(output + "\n")
    else:
        print(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())
